import 'package:cloud_firestore/cloud_firestore.dart';import 'package:firebase_auth/firebase_auth.dart';import 'package:flutter/material.dart';import 'product_service.dart';import 'edit_listing_screen.dart';class MyListingsScreen extends StatelessWidget{const MyListingsScreen({super.key});@override Widget build(BuildContext c){final u=FirebaseAuth.instance.currentUser!.uid;return Scaffold(appBar:AppBar(title:const Text('Iklan Saya')),body:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('products').where('sellerId',isEqualTo:u).snapshots(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());if(s.data!.docs.isEmpty)return const Center(child:Text('Anda belum memiliki iklan'));return ListView(children:s.data!.docs.map((d){final x=d.data();return Card(child:ListTile(title:Text(x['title']??''),subtitle:Text('Rp '+(x['price']??0).toString()+' • '+(x['status']??'active')),trailing:Row(mainAxisSize:MainAxisSize.min,children:[IconButton(icon:const Icon(Icons.edit_outlined),onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>EditListingScreen(id:d.id,data:x)))),IconButton(icon:const Icon(Icons.delete_outline),onPressed:()=>ProductService().deleteProduct(d.id,List<dynamic>.from(x['imageUrls']??[]))) ]));}).toList());}));}}